-- =========================================================
-- 0047 — Fill the empty fields of the 19 programs added in 0046
-- Applied to Supabase on, after 0046.
--
-- Every value was against the program's official page or its owner's
-- official site (links and quotes are kept with the team's documents). Where an official Arabic
-- page exists its wording is used; otherwise the Arabic is a translation of the English.
-- Left empty on purpose: the NCA Cybersecurity Accelerator's target stage (no official page names one).
-- Corrections to 0046 from the official sources:
--   * Khuta (KSU): duration is 12 months incubation, 6 months acceleration (KSU incubation policy), not 36 months.
--   * SparkLabs KSU: funding is up to USD 300,000 (program application form); the 7% share is not stated officially.
--   * Misk Accelerator: the old program page is gone (404); the website is Misk's entrepreneurship page.
-- Services go to organization_services (migration 0043). Running it a second time changes nothing.
-- =========================================================

begin;

update support_organizations set website = 'https://bu.edu.sa/en/departments/departments-and-units/al-baha-university-business-incubator', target_stage = 'Early stage', target_stage_ar = 'المراحل الأولى', updated_at = now() where name = 'Al-Baha University Business Incubator';

update support_organizations set eligibility = 'Ambitious individuals and early-stage teams building in MENAP, full-time or ready to go full-time, solo founders welcome', eligibility_ar = 'أفراد وفرق في مراحلها المبكرة يؤسسون مشاريع في منطقة الشرق الأوسط وشمال أفريقيا وباكستان، متفرغون أو مستعدون للتفرغ، ويُقبل المؤسس المنفرد', updated_at = now() where name = 'Antler (MENAP)';

update support_organizations set target_stage = 'All stages', target_stage_ar = 'جميع المراحل', eligibility = 'Digital entrepreneurs and tech startups', eligibility_ar = 'رواد الأعمال الرقميون والشركات الناشئة التقنية', updated_at = now() where name = 'CODE – Center of Digital Entrepreneurship';

update support_organizations set eligibility = 'Saudi cybersecurity startups with innovative solutions', eligibility_ar = 'شركات سعودية ناشئة في مجال الأمن السيبراني تمتلك حلولًا إبداعية', updated_at = now() where name = 'Cybersecurity Accelerator (NCA)';

update support_organizations set target_stage = 'Seed – Series A (deep tech)', target_stage_ar = 'بذرة – الجولة A (التقنيات العميقة)', eligibility = 'Saudi-based deep-tech startups and global deep-tech companies entering the Saudi market', eligibility_ar = 'شركات ناشئة سعودية في التقنيات العميقة، وشركات تقنية عميقة عالمية تسعى لدخول السوق السعودي', updated_at = now() where name = 'Dhahran Techno Valley (DTV)';

