update support_organizations set eligibility = 'Aspiring founders with an idea who want to build a company (idea to pre-seed)', eligibility_ar = 'رواد أعمال لديهم فكرة ويرغبون في تأسيس شركة (من الفكرة إلى ما قبل البذرة)', updated_at = now() where name = 'Founder Institute (Riyadh)';

update support_organizations set eligibility = 'Seed to Series A tech startups with traction, a scalable product, and an AI/ML focus; CTO must take part', eligibility_ar = 'شركات تقنية ناشئة من مرحلة البذرة حتى الجولة A، لديها نمو ملموس ومنتج قابل للتوسع وتعتمد على الذكاء الاصطناعي، مع مشاركة المدير التقني', updated_at = now() where name = 'Google for Startups Accelerator: MENA-T';

update support_organizations set website = 'https://units.imamu.edu.sa/administrations/en/sustainable/Goals/NoPoverty/Pages/1-4-2.aspx', target_stage = 'Idea / Early stage (pre-incubation, incubation, acceleration)', target_stage_ar = 'الفكرة / المرحلة المبكرة (ما قبل الاحتضان، الاحتضان، التسريع)', updated_at = now() where name = 'Imam Cloud (Imam Muhammad ibn Saud Islamic University)';

update support_organizations set eligibility = 'Early-stage tech startups (General, 3 months, open application); more mature tech startups for the Advanced program (6 months, by invitation); startups from outside the GCC welcome', eligibility_ar = 'شركات تقنية ناشئة في مراحلها الأولية (البرنامج العام، 3 أشهر)؛ وشركات تقنية ناشئة في مراحل أكثر تقدمًا للبرنامج المتقدم (6 أشهر، بالدعوة)؛ ويُرحَّب بالشركات من خارج دول الخليج', updated_at = now() where name = 'InspireU (by stc)';

update support_organizations set target_stage = 'Idea / Prototype – Early stage', target_stage_ar = 'فكرة / نموذج أولي – مرحلة مبكرة', program_duration = '12 months incubation, 6 months acceleration', program_duration_ar = '12 شهرًا للاحتضان، و6 أشهر للتسريع', updated_at = now() where name = 'Khuta Center for Business Incubators and Accelerators (King Saud University)';

update support_organizations set website = 'https://hub.misk.org.sa/misk-entrepreneurship/', updated_at = now() where name = 'Misk Accelerator';

update support_organizations set eligibility = 'Saudi or non-Saudi founders committed to launching in KSA, with idea/prototype/MVP-stage tech ventures; English required; 1–3 founders', eligibility_ar = 'سعوديون أو غير سعوديين ملتزمون بإطلاق مشروعهم في المملكة، بأفكار تقنية في مرحلة الفكرة أو النموذج الأولي أو المنتج الأولي؛ إجادة الإنجليزية؛ من مؤسس إلى 3 مؤسسين', updated_at = now() where name = 'Misk LaunchPad';

update support_organizations set target_stage = 'Idea / Prototype stage', target_stage_ar = 'مرحلة الفكرة / النموذج الأولي', updated_at = now() where name = 'PNU Innovation and Entrepreneurship Center';

update support_organizations set website = 'https://rvc.com.sa/en/riyadh-valley-company-launches-king-saud-university-venture-fund-in-partnership-with-sparklabs/', funding_investment = 'Up to USD 300,000', funding_investment_ar = 'حتى 300,000 دولار أمريكي', eligibility = 'Early-stage startups, especially from King Saud University (students, researchers, faculty), plus promising tech companies', eligibility_ar = 'شركات ناشئة في مراحلها المبكرة، خاصة من جامعة الملك سعود (طلاب وباحثون وأعضاء هيئة تدريس)، إضافة إلى شركات تقنية واعدة', updated_at = now() where name = 'SparkLabs KSU';

update support_organizations set website = 'https://mcit.gov.sa/en/news/mcit-launches-fifth-edition-%E2%80%98tech-champions%E2%80%99-program-empower-fintech-startups', eligibility = 'Fintech entrepreneurs and startup founders with AI-based business models, at prototype or scalable-model stage', eligibility_ar = 'روّاد الأعمال وأصحاب الشركات الناشئة في مجال التقنيات المالية ممن يمتلكون نماذج أعمال قائمة على الذكاء الاصطناعي، في مرحلة النموذج الأولي أو النموذج القابل للتوسع', updated_at = now() where name = 'Tech Champions (by CODE)';

update support_organizations set website = 'https://monshaat.gov.sa/en/node/461312', target_stage = 'Launch stage, with growth potential', target_stage_ar = 'مرحلة الانطلاق، مع قابلية للنمو والتوسع', updated_at = now() where name = 'UBT Accelerator';

update support_organizations set target_stage = 'Early stage (incubation); Seed to Growth (investment)', target_stage_ar = 'مراحل مبكرة (الاحتضان)؛ من البذرة إلى النمو (الاستثمار)', eligibility = 'Local entrepreneurs with early-stage startups in Saudi Arabia', eligibility_ar = 'رواد الأعمال المحليون أصحاب الشركات الناشئة في مراحلها المبكرة في المملكة', updated_at = now() where name = 'Wa''ed Ventures (Aramco)';

commit;
